SELECT jsonb_build_object( 'id',account.id,'steamId',account.steam_id::text,'steamName',account.steam_name, 'discordId',account.discord_id::text,'points',COALESCE(points.points,0), 'rank',COALESCE(points.rank,-1),'totalPoints',COALESCE(points.total_points,0), 'worldRecords',COALESCE(points.world_records,0), 'records',(SELECT count(*) FROM (SELECT * FROM public.record WHERE record_eligible) record WHERE record.id_user=account.id), 'personalBests',COALESCE(points.personal_bests,0), 'publishedLevels',(SELECT count(*) FROM public.level_item item WHERE item.author_id=account.steam_id AND item.deleted=false), 'votes',(SELECT count(*) FROM public.vote vote WHERE vote.id_user=account.id)) AS value FROM public."user" account LEFT JOIN public.user_points points ON points.id_user=account.id WHERE CASE $1 WHEN 'discord' THEN account.discord_id::text=$2 WHEN 'steam' THEN account.steam_id::text=$2 WHEN 'id' THEN account.id::text=$2 ELSE false END LIMIT 1
